import{_ as a,o as s,c as e,a2 as n}from"./chunks/framework.DGu13UIe.js";const g=JSON.parse('{"title":"第 37 课 · 输入循环与 Agent 循环为什么要拆开？（扩展阅读）","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/37-two-loops/doc.md"},"headers":[],"relativePath":"chapters/37-two-loops.md","filePath":"chapters/37-two-loops.md"}'),o={name:"chapters/37-two-loops.md"};function i(d,t,r,p,l,h){return s(),e("div",null,[...t[0]||(t[0]=[n(`<h1 id="第-37-课-·-输入循环与-agent-循环为什么要拆开-扩展阅读" tabindex="-1">第 37 课 · 输入循环与 Agent 循环为什么要拆开？（扩展阅读） <a class="header-anchor" href="#第-37-课-·-输入循环与-agent-循环为什么要拆开-扩展阅读" aria-label="Permalink to &quot;第 37 课 · 输入循环与 Agent 循环为什么要拆开？（扩展阅读）&quot;">​</a></h1><p><strong>约 35 分钟</strong> · 纯阅读 · <a href="/bagent/chapters/36-tool-hooks.html">第 36 课</a> 之后</p><p><a href="/bagent/chapters/27-agent-architecture.html">第 27 课</a> 提过：在 <code>await agent.turn()</code> 期间 <strong>不能边生成边打字</strong>。<br><a href="/bagent/chapters/35-tool-approval.html">第 35–36 课</a> 的 <code>chat.ts</code> 仍是 <strong>一个 <code>while</code> 把两件事串死</strong>。<br> 本课讲清 <strong>两个循环</strong> 为什么要拆，以及为什么在 <strong>单块终端</strong> 里硬做 inbox / steer <strong>性价很低</strong>——根子是 <strong>输入和输出共抢一块 TTY</strong>。</p><p>本课 <strong>不写新代码</strong>（第 24–36 课终端 demo 故意保持串行，降低认知负担）。</p><hr><h2 id="_1-你现在其实有两个循环-但被写成了一个" tabindex="-1">1. 你现在其实有两个循环，但被写成了一个 <a class="header-anchor" href="#_1-你现在其实有两个循环-但被写成了一个" aria-label="Permalink to &quot;1. 你现在其实有两个循环，但被写成了一个&quot;">​</a></h2><p>打开 <a href="/bagent/chapters/36-tool-hooks.html">第 36 课</a> 的 <code>chat.ts</code>，逻辑是：</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> rl.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">question</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;你: &quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ① 输入</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  for</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> event</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> of</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> agent.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">turn</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)) { </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// ② Agent</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    handleTerminalEvent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(event, uiState);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>概念上这是 <strong>两条循环</strong>，只是用 <code>await</code> <strong>串成一条链</strong>：</p><table tabindex="0"><thead><tr><th>循环</th><th>干什么</th><th>在代码里</th></tr></thead><tbody><tr><td><strong>输入循环</strong></td><td>读键盘、显示提示、收审批 <code>y/N</code></td><td><code>rl.question</code>、<code>approve</code></td></tr><tr><td><strong>Agent 循环</strong></td><td>调 API、流式事件、跑工具、写 history</td><td><code>agent.turn</code> → <code>loop</code> → <code>stream</code></td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现在的写法（串行）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  输入 ──await──► Agent turn ──await──► 输入 ──await──► Agent turn …</span></span>
<span class="line"><span>         ↑                              ↑</span></span>
<span class="line"><span>    只有 turn 完全结束，才回到 question</span></span></code></pre></div><p>对产品来说，你希望的是：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>想要的（并发交错）：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  输入 ──┐                    ┌── 随时能打字</span></span>
<span class="line"><span>         ├── 中间用队列/消息 ──┤</span></span>
<span class="line"><span>  Agent ─┘                    └── 边流式输出边收新指令</span></span></code></pre></div><p><strong>拆开</strong>的意思不是「一定要两个进程」，而是：<strong>别让 <code>question()</code> 和 <code>turn()</code> 互相 <code>await</code> 卡在同一根调用链上</strong>。</p><hr><h2 id="_2-为什么-await-了还能流式-却不能插嘴" tabindex="-1">2. 为什么 <code>await</code> 了还能流式，却不能插嘴？ <a class="header-anchor" href="#_2-为什么-await-了还能流式-却不能插嘴" aria-label="Permalink to &quot;2. 为什么 \`await\` 了还能流式，却不能插嘴？&quot;">​</a></h2><p><a href="/bagent/chapters/27-agent-architecture.html">第 27 课</a> 4.4 节的时间线再压缩一下：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>chat: await rl.question()        ← 事件循环在等键盘，可以</span></span>
<span class="line"><span>chat: for await (agent.turn())   ← 外层卡在这一行</span></span>
<span class="line"><span>  stream: await reader.read()    ← 等网络时 JS 让出 CPU，可以处理别的微任务</span></span>
<span class="line"><span>  yield ChunkUpdated             ← 终端继续打字</span></span>
<span class="line"><span>  await approve() → rl.question  ← 审批时又能读键盘，但……</span></span></code></pre></div><p>容易误会的一点：</p><blockquote><p>「流式时 <code>await reader.read()</code> 会让出事件循环，所以应该能同时读 stdin 吧？」</p></blockquote><p><strong>不能</strong>——因为外层已经进了 <code>for await (turn)</code>，<strong>没有第二个 <code>rl.question()</code> 在跑</strong>。<br> 事件循环空闲时可以去干别的事，但你的 <code>chat.ts</code> <strong>没安排</strong>「读下一条用户话」这段逻辑。</p><p>审批是 <strong>唯一例外</strong>：<code>approve</code> 在 <code>turn</code> <strong>内部</strong> 又调了一次 <code>question</code>，所以工具前你能按 <code>y/N</code>——但那是 <strong>嵌在 Agent 管线里的输入</strong>，不是「随便插一句新话题」。</p><table tabindex="0"><thead><tr><th>场景</th><th>第 36 课能不能</th></tr></thead><tbody><tr><td>AI 流式打字时，你再输入「停，别读了」</td><td>❌</td></tr><tr><td>工具审批 <code>y/N</code></td><td>✅（<code>approve</code> 在 turn 里）</td></tr><tr><td>AI 思考时改主意</td><td>❌</td></tr><tr><td><code>/quit</code> 立刻结束（不等 turn 完）</td><td>❌（要等当前 turn 结束或报错）</td></tr></tbody></table><hr><h2 id="_3-拆开之后长什么样-概念" tabindex="-1">3. 拆开之后长什么样（概念） <a class="header-anchor" href="#_3-拆开之后长什么样-概念" aria-label="Permalink to &quot;3. 拆开之后长什么样（概念）&quot;">​</a></h2><h3 id="_3-1-同进程-两个-async-任务-信箱" tabindex="-1">3.1 同进程：两个 async 任务 + 信箱 <a class="header-anchor" href="#_3-1-同进程-两个-async-任务-信箱" aria-label="Permalink to &quot;3.1 同进程：两个 async 任务 + 信箱&quot;">​</a></h3><p>仍在 <strong>一个 Node 进程</strong>、一个事件循环里，可以写成：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│  任务 A：输入循环（一直跑）               │</span></span>
<span class="line"><span>│    line = await rl.question()           │</span></span>
<span class="line"><span>│    inbox.push(line)                     │</span></span>
<span class="line"><span>├─────────────────────────────────────────┤</span></span>
<span class="line"><span>│  任务 B：Agent 循环（一直跑）             │</span></span>
<span class="line"><span>│    msg = await inbox.take()             │</span></span>
<span class="line"><span>│    for await (event of turn(msg)) …     │</span></span>
<span class="line"><span>└─────────────────────────────────────────┘</span></span></code></pre></div><ul><li><strong>A 从不 <code>await turn()</code></strong>——只往信箱塞字符串</li><li><strong>B 消费信箱、产出事件</strong></li><li>若 AI 还在流式输出时你又敲了一行，队列里 <strong>先堆着</strong>（FIFO）；<strong>steer</strong> 则是插队改向，要另加规则</li></ul><h3 id="_3-2-双进程-第-28-31-课已经「物理拆开」" tabindex="-1">3.2 双进程：第 28 / 31 课已经「物理拆开」 <a class="header-anchor" href="#_3-2-双进程-第-28-31-课已经「物理拆开」" aria-label="Permalink to &quot;3.2 双进程：第 28 / 31 课已经「物理拆开」&quot;">​</a></h3><p><a href="/bagent/chapters/28-agent-network.html">第 28 课</a>：<code>client</code> 与 <code>server</code> 各有一个事件循环。<br><a href="/bagent/chapters/31-vscode-spawn.html">第 31 课</a>：侧边栏 Webview + worker 子进程。</p><table tabindex="0"><thead><tr><th>拆法</th><th>进程数</th><th>本课程例子</th></tr></thead><tbody><tr><td>串行 <code>await</code></td><td>1</td><td>第 24–36 课 <code>chat.ts</code></td></tr><tr><td>队列 + 双任务</td><td>1</td><td>概念可行，见下节终端局限</td></tr><tr><td>网络 / stdio IPC</td><td>2+</td><td>第 28、31 课</td></tr></tbody></table><hr><h2 id="_4-更尴尬的一层-输入和输出共用终端" tabindex="-1">4. 更尴尬的一层：输入和输出共用终端 <a class="header-anchor" href="#_4-更尴尬的一层-输入和输出共用终端" aria-label="Permalink to &quot;4. 更尴尬的一层：输入和输出共用终端&quot;">​</a></h2><p>第 3 节解决的是 <strong>JS 里谁 <code>await</code> 谁</strong>。还有一层更根本：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单块 TTY（第 24–36 课）</span></span>
<span class="line"><span>┌──────────────────────────────┐</span></span>
<span class="line"><span>│  stdout：【思考】、AI 字、工具   │</span></span>
<span class="line"><span>│  stdin：  readline 的 「你:」  │  ← 同一窗口，同一光标</span></span>
<span class="line"><span>└──────────────────────────────┘</span></span></code></pre></div><p><code>handleTerminalEvent</code> 往 <strong>stdout</strong> 流式 <code>write</code>；<code>rl.question</code> 在 <strong>同一屏</strong> 底部占一行当提示符。<br> 即使用双循环 + inbox，只要还在 <strong>readline + console.log</strong> 模型里，就会：</p><ul><li>AI 打字和 <code>你:</code> / <code>y/N</code> <strong>抢行</strong></li><li>每个流式 token 若刷新 prompt，会刷满屏 <code>(忙碌中)</code></li><li><code>rl.pause()</code> / 少刷 prompt 只是 <strong>协调补丁</strong>，不是分区</li></ul><p><strong>结论</strong>：inbox、cancel、<code>AbortSignal</code> 在 <strong>内核层</strong> 仍然正确；但在 <strong>单屏 readline</strong> 里做完整产品，投入大、体验差。<br> 终端产品要走 <strong>CLI + TUI 分屏</strong>（<a href="/bagent/chapters/38-agent-product.html">第 38 课</a> 产品 ①）；插件走 <strong>Webview 分屏</strong>（产品 ②）。不在 readline 单屏上硬做 inbox 课。</p><hr><h2 id="_5-解决方案-按推荐顺序" tabindex="-1">5. 解决方案（按推荐顺序） <a class="header-anchor" href="#_5-解决方案-按推荐顺序" aria-label="Permalink to &quot;5. 解决方案（按推荐顺序）&quot;">​</a></h2><h3 id="_5-1-浏览器-网页-聊天区-输入框-推荐先做" tabindex="-1">5.1 浏览器 / 网页：聊天区 + 输入框（推荐先做） <a class="header-anchor" href="#_5-1-浏览器-网页-聊天区-输入框-推荐先做" aria-label="Permalink to &quot;5.1 浏览器 / 网页：聊天区 + 输入框（推荐先做）&quot;">​</a></h3><p><a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 模式：server 产 <code>AgentEvent</code>，SSE 推到前端。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────┐</span></span>
<span class="line"><span>│ 消息区（div）     │  ← ChunkUpdated、Thinking、工具行</span></span>
<span class="line"><span>├─────────────────┤</span></span>
<span class="line"><span>│ &lt;textarea&gt; 发送  │  ← 与流式输出无关</span></span>
<span class="line"><span>└─────────────────┘</span></span></code></pre></div><p>内核仍是 <code>loop</code> + hooks + <code>approve</code>；<strong>换 UI 壳</strong>，不跟 stdout 抢。<br> inbox、cancel 在网页里自然：输入框常显，Cancel 按钮 <code>AbortSignal</code>。</p><h3 id="_5-2-ide-webview-第-31–32-课方向" tabindex="-1">5.2 IDE Webview（第 31–32 课方向） <a class="header-anchor" href="#_5-2-ide-webview-第-31–32-课方向" aria-label="Permalink to &quot;5.2 IDE Webview（第 31–32 课方向）&quot;">​</a></h3><p>侧边栏 <strong>上消息、下输入</strong>；<code>ToolCallPending</code> → 批准按钮。<br> 与 Cursor / VS Code 插件同款；要把 <a href="/bagent/chapters/34-agent-thinking.html">第 34–36 课</a> 的事件与钩子同步进 worker。</p><h3 id="_5-3-终端-tui-分屏-→-产品-1-cli-第-38-课" tabindex="-1">5.3 终端 TUI 分屏 → <strong>产品 ① CLI</strong>（第 38 课） <a class="header-anchor" href="#_5-3-终端-tui-分屏-→-产品-1-cli-第-38-课" aria-label="Permalink to &quot;5.3 终端 TUI 分屏 → **产品 ① CLI**（第 38 课）&quot;">​</a></h3><p>不用 readline 混写，<strong>bagent CLI</strong> 用全屏 TUI 划两块：</p><table tabindex="0"><thead><tr><th>库</th><th>思路</th></tr></thead><tbody><tr><td><a href="https://github.com/vadimdemedes/ink" target="_blank" rel="noreferrer">Ink</a></td><td><code>&lt;Static&gt;</code> 历史 + 底部 <code>&lt;TextInput&gt;</code></td></tr><tr><td><code>blessed</code> / <code>neo-blessed</code></td><td>上 <code>log</code> 框 + 下 <code>textbox</code></td></tr></tbody></table><p>Agent 循环只更新 <strong>上方消息区</strong>；输入 <strong>永远在底栏</strong>——与插件 Webview <strong>同构</strong>，只是渲染从 DOM 换成 TUI。</p><h3 id="_5-4-终端内协调-第-36-课-有天花板" tabindex="-1">5.4 终端内协调（第 36 课，有天花板） <a class="header-anchor" href="#_5-4-终端内协调-第-36-课-有天花板" aria-label="Permalink to &quot;5.4 终端内协调（第 36 课，有天花板）&quot;">​</a></h3><p>串行 <code>question</code> → <code>turn</code>，审批嵌在 <code>turn</code> 里。<br><strong>够学 Loop</strong>；不追求 steer、不边流式边插话。<br> 双循环 + <code>rl.pause()</code> 属此档补丁，本课 <strong>不单独开课</strong>。</p><h3 id="_5-5-对照" tabindex="-1">5.5 对照 <a class="header-anchor" href="#_5-5-对照" aria-label="Permalink to &quot;5.5 对照&quot;">​</a></h3><table tabindex="0"><thead><tr><th>方案</th><th>输出</th><th>输入</th><th>本课建议</th></tr></thead><tbody><tr><td>readline 单屏</td><td>stdout 流式</td><td>同行 prompt</td><td>24–36 <strong>学内核</strong></td></tr><tr><td>TUI 分屏</td><td>上面板</td><td>底栏</td><td><strong>产品 ① CLI</strong></td></tr><tr><td>Webview 分屏</td><td>消息区 DOM</td><td>独立输入框</td><td><strong>产品 ② 插件</strong></td></tr></tbody></table><hr><h2 id="_6-和「渲染」的关系" tabindex="-1">6. 和「渲染」的关系 <a class="header-anchor" href="#_6-和「渲染」的关系" aria-label="Permalink to &quot;6. 和「渲染」的关系&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>做什么</th></tr></thead><tbody><tr><td><strong>输入循环</strong></td><td>收用户字、命令、审批</td></tr><tr><td><strong>Agent 循环</strong></td><td>turn、工具、history</td></tr><tr><td><strong>渲染</strong></td><td><code>AgentEvent</code> → 终端 / Webview / TUI 面板</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>键盘 → 输入循环 → inbox（概念）</span></span>
<span class="line"><span>inbox → Agent 循环 → AgentEvent → 渲染（必须和输入区分开屏）</span></span></code></pre></div><hr><h2 id="_7-后续课程会怎么接" tabindex="-1">7. 后续课程会怎么接 <a class="header-anchor" href="#_7-后续课程会怎么接" aria-label="Permalink to &quot;7. 后续课程会怎么接&quot;">​</a></h2><table tabindex="0"><thead><tr><th>能力</th><th>你会在哪遇到</th></tr></thead><tbody><tr><td>双循环 + inbox</td><td>概念在本课；<strong>动手</strong>在 TUI / Webview（输入输出已分屏）</td></tr><tr><td>Cancel / <code>AbortSignal</code></td><td>与分屏 UI、server 一起做</td></tr><tr><td>Steer（流式中插话）</td><td>独立输入框的产品里（如 Kimi 的 <code>Ctrl-S</code>）</td></tr><tr><td>Thinking、审批、钩子</td><td>ch34–36 已学；ch28 server / ch31 worker 将来对齐</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第 36 课：串行终端 chat（学完内核即可）</span></span>
<span class="line"><span>第 37 课：两个循环 + 单 TTY 局限（本课）</span></span>
<span class="line"><span>第 38 课：三种产品形态</span></span>
<span class="line"><span>第 39 课：ACP（IDE 行业标准）</span></span></code></pre></div><hr><h2 id="_8-审批放在哪" tabindex="-1">8. 审批放在哪？ <a class="header-anchor" href="#_8-审批放在哪" aria-label="Permalink to &quot;8. 审批放在哪？&quot;">​</a></h2><p><a href="/bagent/chapters/36-tool-hooks.html">第 36 课</a> 的 <code>approvalBefore</code> 在终端里仍要读键盘。</p><table tabindex="0"><thead><tr><th>放法</th><th>场景</th></tr></thead><tbody><tr><td><strong>A. turn 内 await 审批</strong></td><td>第 36 课终端 <code>y/N</code></td></tr><tr><td><strong>B. 事件 + 按钮</strong></td><td>Webview；<a href="/bagent/chapters/17-sse-landscape.html">第 17 课</a> JSON-RPC <code>request</code> 同构</td></tr></tbody></table><p>分屏 UI 下用 <strong>B</strong>；单屏终端只能用 <strong>A</strong>，且和流式输出抢行。</p><hr><h2 id="_9-常见误解" tabindex="-1">9. 常见误解 <a class="header-anchor" href="#_9-常见误解" aria-label="Permalink to &quot;9. 常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>正解</th></tr></thead><tbody><tr><td>「拆开双循环 = 终端体验就好了」</td><td>还要 <strong>输入区 / 输出区分开</strong></td></tr><tr><td>「有流式就能插嘴」</td><td>流式只解决输出边显；单屏 readline 仍挡路</td></tr><tr><td>「双进程就自动 steer」</td><td>第 28 课 client 仍可一发一收</td></tr><tr><td>「inbox 在终端值得一整课」</td><td>内核有用；<strong>单 TTY demo 性价比低</strong>，见 §4</td></tr></tbody></table><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 「输入循环」和「Agent 循环」在 <code>chat.ts</code> 里各对应哪几行？</li><li>[ ] 为什么流式 <code>await reader.read()</code> 不等于「能边输出边读新用户话」？</li><li>[ ] <strong>stdout 和 readline 为什么会在同一终端里抢？</strong></li><li>[ ] 网页分屏、Webview、TUI 分别怎么避开这个问题？</li><li>[ ] 为什么本课不在终端单独做 inbox 动手课？</li></ul><hr><p><a href="/bagent/chapters/36-tool-hooks.html">← 第 36 课</a> · <a href="/bagent/chapters/38-agent-product.html">第 38 课 · 三种产品形态</a> · <a href="/bagent/chapters/27-agent-architecture.html">第 27 课</a></p>`,76)])])}const b=a(o,[["render",i]]);export{g as __pageData,b as default};
